  body {
    font-family: var(--font);
    background: var(--white);
    color: var(--navy);
    font-size: 14px;
    line-height: 1.5;
  }

  a { color: inherit; text-decoration: none; }

  /* ─── TOP STATS BAR ─── */
  .stats-bar {
    background: var(--white);
    border-bottom: 1px solid var(--border);
    padding: 8px 0;
    font-size: 12px;
    color: var(--gray);
    overflow-x: auto;
    white-space: nowrap;
  }
  .stats-bar-inner {
    max-width: 1440px;
    margin: 0 auto;
    padding: 0 16px;
    display: flex;
    align-items: center;
