  .nav-inner {
    max-width: 1440px;
    margin: 0 auto;
    padding: 0 16px;
    display: flex;
    align-items: center;
    height: 56px;
    gap: 0;
  }
  .brand {
    font-size: 16px;
    font-weight: 700;
