    font-size: 13.5px;
    font-weight: 500;
    color: var(--gray);
    transition: color .15s;
    white-space: nowrap;
  }
  .nav-links a:hover { color: var(--navy); }
  .nav-links a.active { color: var(--navy); border-bottom: 2px solid var(--blue); }
  .nav-links .chevron { font-size: 10px; }
  .nav-auth {
    display: flex;
    align-items: center;
    gap: 8px;
    margin-left: auto;
  }
  .btn-login {
    padding: 7px 16px;
    border-radius: 6px;
    font-size: 13px;
    font-weight: 600;
    color: var(--blue);
    border: 1.5px solid var(--blue);
    background: transparent;
    cursor: pointer;
    transition: background .15s;
  }
  .btn-login:hover { background: rgba(56,97,251,.06); }
  .btn-signup {
    padding: 7px 16px;
    border-radius: 6px;
