  /* ─── PROMO BANNER ─── */
  .promo-banner {
    background: linear-gradient(90deg, #0a1628 0%, #1a2e5a 50%, #0a1628 100%);
    color: white;
    text-align: center;
    padding: 9px 16px;
    font-size: 13px;
    position: relative;
    overflow: hidden;
    cursor: pointer;
