  .promo-slide { display: none; }
  .promo-slide.active { display: block; }
  .promo-slide a { color: #60a5fa; font-weight: 600; margin-left: 8px; }
  .promo-nav {
    position: absolute;
    right: 16px;
    top: 50%;
    transform: translateY(-50%);
    display: flex;
    gap: 6px;
