    padding: 10px 0;
    overflow-x: auto;
  }
  .ai-bar-inner {
    max-width: 1440px;
    margin: 0 auto;
    padding: 0 16px;
    display: flex;
    align-items: center;
    gap: 10px;
    white-space: nowrap;
  }
  .ai-icon {
    background: var(--blue);
    color: white;
    font-size: 11px;
    font-weight: 700;
    padding: 3px 7px;
    border-radius: 4px;
    flex-shrink: 0;
  }
  .ai-topic {
    font-size: 13px;
    font-weight: 600;
    color: var(--navy);
    margin-right: 6px;
    flex-shrink: 0;
  }
  .ai-suggestions { display: flex; gap: 7px; }
  .ai-chip {
    background: white;
    border: 1px solid #C7D4FD;
    border-radius: 999px;
    padding: 4px 11px;
    font-size: 12px;
    color: var(--blue);
    cursor: pointer;
    transition: background .15s;
    white-space: nowrap;
  }
  .ai-chip:hover { background: #EEF2FF; }

  /* ─── MAIN CONTENT ─── */
  .main {
    max-width: 1440px;
    margin: 0 auto;
    padding: 0 16px 32px;
  }

  /* ─── PAGE TITLE ─── */
  .page-header {
    padding: 24px 0 16px;
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    flex-wrap: wrap;
    gap: 12px;
  }
  .page-title { font-size: 22px; font-weight: 700; color: var(--navy); }
  .page-sub { font-size: 13px; color: var(--gray); margin-top: 2px; }

  /* ─── OVERVIEW STATS CARDS ─── */
  .overview-row {
    display: flex;
    gap: 12px;
    margin-bottom: 20px;
    flex-wrap: wrap;
  }
  .overview-card {
    background: var(--white);
    border: 1px solid var(--border);
    border-radius: 10px;
    padding: 14px 20px;
    flex: 1;
    min-width: 180px;
  }
  .ov-label { font-size: 11px; color: var(--gray); text-transform: uppercase; letter-spacing: .5px; margin-bottom: 5px; }
  .ov-value { font-size: 20px; font-weight: 700; color: var(--navy); line-height: 1.2; }
  .ov-change { font-size: 12px; margin-top: 3px; }
  .ov-change.up { color: var(--green); }
  .ov-change.dn { color: var(--red); }
  .ov-change.nu { color: var(--gray); }
  .fear-gauge {
    display: flex;
    align-items: center;
    gap: 8px;
    margin-top: 4px;
  }
  .fear-number { font-size: 24px; font-weight: 700; color: #f59e0b; }
  .fear-label-pill {
    background: #FEF3C7;
    color: #92400E;
    font-size: 11px;
    font-weight: 600;
    padding: 2px 8px;
    border-radius: 999px;
  }

  /* ─── INDEX ROW ─── */
  .index-row {
    background: #F0F4FF;
    border: 1px solid #DDE5FF;
    border-radius: 8px;
    padding: 10px 16px;
    display: flex;
    align-items: center;
    gap: 24px;
    margin-bottom: 16px;
    flex-wrap: wrap;
  }
  .index-label { font-size: 12px; color: var(--gray); margin-bottom: 1px; }
  .index-name { font-size: 13px; font-weight: 600; color: var(--navy); }
  .index-price { font-size: 15px; font-weight: 700; color: var(--navy); font-variant-numeric: tabular-nums; }
  .index-pct { font-size: 12px; font-weight: 600; }
  .index-pct.up { color: var(--green); }
  .idx-group { display: flex; align-items: center; gap: 16px; margin-left: auto; flex-wrap: wrap; }
  .idx-stat { text-align: center; }
  .idx-stat-label { font-size: 11px; color: var(--gray); }
  .idx-stat-val { font-size: 13px; font-weight: 600; }

  /* ─── CATEGORY TABS ─── */
  .tabs-row {
    display: flex;
    align-items: center;
    gap: 2px;
    margin-bottom: 12px;
    border-bottom: 1px solid var(--border);
  }
  .tab-btn {
    padding: 9px 16px;
    font-size: 13px;
    font-weight: 500;
    color: var(--gray);
    background: none;
    border: none;
    cursor: pointer;
    border-bottom: 2px solid transparent;
    margin-bottom: -1px;
    transition: color .15s;
    white-space: nowrap;
  }
  .tab-btn:hover { color: var(--navy); }
  .tab-btn.active {
    color: var(--navy);
    font-weight: 600;
    border-bottom-color: var(--blue);
  }
  .tab-more {
    color: var(--blue);
    font-size: 13px;
    padding: 9px 12px;
    cursor: pointer;
    margin-bottom: -1px;
    border-bottom: 2px solid transparent;
  }

  /* ─── NETWORK FILTER TABS ─── */
  .network-row {
    display: flex;
    align-items: center;
    gap: 6px;
    margin-bottom: 12px;
    flex-wrap: wrap;
  }
  .network-btn {
    padding: 5px 13px;
    border-radius: 999px;
    font-size: 12px;
    font-weight: 500;
    color: var(--gray);
    background: none;
    border: 1.5px solid var(--border);
    cursor: pointer;
    transition: all .15s;
    white-space: nowrap;
  }
  .network-btn:hover { border-color: var(--blue); color: var(--blue); }
  .network-btn.active {
    background: var(--blue);
    color: white;
    border-color: var(--blue);
  }

  /* ─── TABLE CONTROLS ─── */
  .table-controls {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 10px;
    flex-wrap: wrap;
    gap: 8px;
  }
  .table-ctrl-left { display: flex; align-items: center; gap: 6px; }
  .sort-btn {
    padding: 6px 12px;
    border-radius: 6px;
    font-size: 12px;
    font-weight: 500;
    color: var(--gray);
    background: none;
    border: 1px solid var(--border);
    cursor: pointer;
  }
  .sort-btn.active { color: var(--navy); font-weight: 600; border-color: #C0CADD; background: var(--light-gray); }
  .ctrl-btn {
    padding: 6px 12px;
    border-radius: 6px;
    font-size: 12px;
    font-weight: 500;
    color: var(--navy);
    background: none;
    border: 1px solid var(--border);
    cursor: pointer;
    display: flex;
    align-items: center;
    gap: 5px;
    transition: background .15s;
  }
  .ctrl-btn:hover { background: var(--light-gray); }
  .ctrl-btn svg { width: 13px; height: 13px; }

  /* ─── FILTER PANEL ─── */
  .filter-panel {
    display: none;
    background: var(--light-gray);
    border: 1px solid var(--border);
    border-radius: 8px;
    padding: 16px 20px;
    margin-bottom: 12px;
  }
  .filter-panel.open { display: flex; gap: 24px; flex-wrap: wrap; }
  .filter-group label { font-size: 11px; color: var(--gray); text-transform: uppercase; letter-spacing: .5px; display: block; margin-bottom: 6px; }
  .filter-group select, .filter-group input {
    border: 1px solid var(--border);
    border-radius: 6px;
    padding: 6px 10px;
    font-size: 13px;
    color: var(--navy);
    background: white;
    width: 160px;
  }

  /* ─── COLUMNS PANEL ─── */
  .columns-panel {
    display: none;
    background: white;
    border: 1px solid var(--border);
    border-radius: 8px;
    padding: 16px 20px;
    margin-bottom: 12px;
    box-shadow: 0 4px 16px rgba(0,0,0,.08);
