  .columns-panel.open { display: flex; gap: 16px; flex-wrap: wrap; }
  .col-toggle { display: flex; align-items: center; gap: 6px; cursor: pointer; font-size: 13px; color: var(--navy); }
  .col-toggle input[type=checkbox] { accent-color: var(--blue); width: 14px; height: 14px; }

  /* ─── RANKINGS TABLE ─── */
  .table-wrap {
    overflow-x: auto;
