    font-size: 13.5px;
  }
  thead tr {
    border-bottom: 2px solid var(--border);
    background: var(--light-gray);
  }
  th {
    padding: 11px 12px;
    text-align: right;
    font-size: 11.5px;
    font-weight: 600;
    color: var(--gray);
    white-space: nowrap;
    cursor: pointer;
    user-select: none;
  }
  th:hover { color: var(--navy); }
  th.left { text-align: left; }
  th.sort-active { color: var(--navy); }
  th .sort-arrow { font-size: 9px; margin-left: 3px; }

  tbody tr {
    border-bottom: 1px solid var(--border);
