  .coin-name { font-weight: 600; font-size: 13.5px; color: var(--navy); }
  .coin-sym { font-size: 11px; color: var(--gray); font-weight: 500; }

  td.pct-up { color: var(--green); font-weight: 500; }
  td.pct-dn { color: var(--red); font-weight: 500; }
  td.pct-nu { color: var(--gray); font-weight: 500; }

  td .price-val { font-size: 13.5px; }

  /* Sparkline */
