    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 14px 16px;
    border-top: 1px solid var(--border);
    background: var(--light-gray);
    border-radius: 0 0 10px 10px;
    flex-wrap: wrap;
    gap: 8px;
  }
  .page-info { font-size: 12px; color: var(--gray); }
  .page-btns { display: flex; gap: 4px; align-items: center; }
  .page-btn {
    width: 32px;
    height: 32px;
    border-radius: 6px;
    border: 1px solid var(--border);
    background: white;
    font-size: 13px;
    color: var(--navy);
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: all .15s;
  }
  .page-btn:hover { border-color: var(--blue); color: var(--blue); }
  .page-btn.active { background: var(--blue); color: white; border-color: var(--blue); font-weight: 600; }
  .page-ellipsis { color: var(--gray); padding: 0 4px; font-size: 13px; }

  /* ─── MARKET SUMMARY ─── */
  .market-summary {
    background: var(--white);
    border: 1px solid var(--border);
    border-radius: 10px;
    padding: 20px 24px;
    margin-top: 24px;
  }
  .ms-title { font-size: 15px; font-weight: 700; color: var(--navy); margin-bottom: 10px; }
  .ms-text { font-size: 13.5px; color: #4A5568; line-height: 1.7; }
  .ms-text b { color: var(--navy); }
  .ms-hidden { display: none; }
  .ms-read-more {
    color: var(--blue);
    font-size: 13px;
    font-weight: 600;
    cursor: pointer;
    margin-top: 8px;
    display: inline-flex;
    align-items: center;
    gap: 4px;
  }

  /* ─── INFO CONTENT ─── */
  .info-content {
    margin-top: 32px;
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 20px;
  }
  @media(max-width: 720px) { .info-content { grid-template-columns: 1fr; } }
  .info-block { }
  .info-block h3 { font-size: 14px; font-weight: 700; color: var(--navy); margin-bottom: 6px; }
  .info-block p { font-size: 13px; color: #4A5568; line-height: 1.65; }

  /* ─── FOOTER ─── */
  footer {
    background: #0D1421;
    color: #808A9D;
    margin-top: 48px;
    padding: 40px 0 24px;
  }
  .footer-inner {
    max-width: 1440px;
    margin: 0 auto;
    padding: 0 16px;
  }
  .footer-top {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 32px;
    margin-bottom: 32px;
  }
  @media(max-width: 720px) { .footer-top { grid-template-columns: 1fr 1fr; } }
  .footer-brand { grid-column: span 1; }
  .footer-brand-name { font-size: 15px; font-weight: 700; color: white; margin-bottom: 8px; }
  .footer-col h4 { font-size: 12px; font-weight: 700; color: white; text-transform: uppercase; letter-spacing: .6px; margin-bottom: 12px; }
  .footer-col ul { list-style: none; display: flex; flex-direction: column; gap: 8px; }
  .footer-col a { font-size: 13px; color: #808A9D; transition: color .15s; }
  .footer-col a:hover { color: white; }
  .footer-bottom {
    border-top: 1px solid #1E2D42;
    padding-top: 20px;
    font-size: 12px;
    color: #4A5568;
    text-align: center;
  }

  /* ─── RESPONSIVE ─── */
  @media(max-width: 900px) {
    .nav-links { display: none; }
    .overview-row { gap: 8px; }
    .overview-card { min-width: 140px; padding: 12px 14px; }
    .ov-value { font-size: 17px; }
    th, td { padding: 10px 8px; }
    .coin-cell { min-width: 120px; }
    td.col-supply, th.col-supply { display: none; }
    td.col-1h, th.col-1h { display: none; }
  }

  /* Number formatting helpers */
  .num { font-variant-numeric: tabular-nums; }
</style>
</head>
