// Sparkline SVG generator
function sparklineSVG(trend, color) {
  const W = 80, H = 32, pts = 14;
  // Generate a plausible mini price series
  let vals = [];
  let v = 50;
  for (let i = 0; i < pts; i++) {
    v += (Math.random() - 0.48 + trend * 0.08) * 12;
    v = Math.max(5, Math.min(95, v));
    vals.push(v);
  }
  const min = Math.min(...vals), max = Math.max(...vals);
  const range = max - min || 1;
  const points = vals.map((y, x) =>
    `${(x / (pts - 1) * W).toFixed(1)},${((1 - (y - min) / range) * H).toFixed(1)}`
  ).join(' ');
  return `<svg width="${W}" height="${H}" viewBox="0 0 ${W} ${H}" fill="none" xmlns="http://www.w3.org/2000/svg">
    <polyline points="${points}" stroke="${color}" stroke-width="1.5" stroke-linejoin="round" stroke-linecap="round" fill="none"/>
  </svg>`;
}

