    coins = coins.slice().sort((a,b) => Math.abs(b.d24) - Math.abs(a.d24)).slice(0, 100);
  } else if (currentCat === 'watchlist') {
    coins = coins.slice(0, 10); // demo
  } else if (currentCat === 'new') {
    coins = coins.slice(80);
  } else if (currentCat === 'visited') {
    coins = coins.slice().sort(() => Math.random() - 0.5).slice(0, 50);
  }

  // Network filter (demo — just reduce list for non-all)
  if (currentNet === 'bsc') {
    coins = coins.filter((_,i) => i % 5 === 0 || i < 6);
  } else if (currentNet === 'solana') {
    coins = coins.filter((_,i) => i % 7 === 0 || i === 5);
  } else if (currentNet === 'base') {
    coins = coins.filter((_,i) => i % 9 === 0 || i < 3);
  } else if (currentNet === 'ethereum') {
    coins = coins.filter((_,i) => i % 3 === 0 || i < 5);
  }

  // Sort
  coins.sort((a, b) => {
    const dir = sortDir === 'asc' ? 1 : -1;
    const fields = {
      marketcap: [a.mcap, b.mcap],
      volume: [a.vol, b.vol],
      price: [a.price, b.price],
      '1h': [a.h1, b.h1],
      '24h': [a.d24, b.d24],
      '7d': [a.d7, b.d7],
    };
    const [av, bv] = fields[sortField] || [a.mcap, b.mcap];
    return (bv - av) * dir;
  });

  return coins;
}

