    `Showing ${start + 1}–${Math.min(start + perPage, total)} of ${total.toLocaleString()} assets`;

  const tbody = document.getElementById('tableBody');
  tbody.innerHTML = '';

  page.forEach((coin, idx) => {
    const tr = document.createElement('tr');
    const sparkColor = coin.d7 >= 0 ? '#16c784' : '#ea3943';
    const priceStr = coin.price >= 1
      ? '$' + fmt(coin.price)
      : '$' + coin.price.toPrecision(4);

    tr.innerHTML = `
      <td class="left rank">${start + idx + 1}</td>
      <td class="star"><span class="star-icon">☆</span></td>
      <td class="left">
        <div class="coin-cell">
          <div class="coin-icon" style="background:${coin.color}">${coin.icon}</div>
          <div>
            <div class="coin-name">${coin.name}</div>
            <div class="coin-sym">${coin.sym}</div>
          </div>
        </div>
      </td>
      <td class="col-price"><span class="price-val">${priceStr}</span></td>
      <td class="col-1h ${pctClass(coin.h1)}">${pctFmt(coin.h1)}</td>
      <td class="col-24h ${pctClass(coin.d24)}">${pctFmt(coin.d24)}</td>
      <td class="col-7d ${pctClass(coin.d7)}">${pctFmt(coin.d7)}</td>
      <td class="col-marketcap">${fmtB(coin.mcap)}</td>
      <td class="col-volume">${fmtB(coin.vol)}</td>
      <td class="col-supply">${coin.supply}</td>
      <td class="col-sparkline">${sparklineSVG(coin.d7, sparkColor)}</td>
    `;
    tbody.appendChild(tr);
  });
}

// ─── PAGINATION ───────────────────────────────────────────────────────────────

function setupPagination() {
  document.getElementById('pageBtns').addEventListener('click', e => {
    const btn = e.target.closest('.page-btn');
    if (!btn) return;
    const txt = btn.textContent.trim();
    if (txt === '›') {
      currentPage++;
    } else if (!isNaN(txt)) {
      currentPage = parseInt(txt, 10);
    }
    document.querySelectorAll('.page-btn').forEach(b => b.classList.remove('active'));
    if (!isNaN(txt)) btn.classList.add('active');
    renderTable();
    window.scrollTo({top: 0, behavior: 'smooth'});
  });
}

// ─── SORT ────────────────────────────────────────────────────────────────────

document.querySelectorAll('th[data-sort]').forEach(th => {
  th.addEventListener('click', () => {
    const field = th.dataset.sort;
    if (sortField === field) {
      sortDir = sortDir === 'desc' ? 'asc' : 'desc';
    } else {
      sortField = field;
      sortDir = 'desc';
    }
    document.querySelectorAll('th').forEach(t => t.classList.remove('sort-active'));
    th.classList.add('sort-active');
    currentPage = 1;
    renderTable();
  });
});

// Sort buttons (Market Cap / Volume)
document.getElementById('sortMarketCap').addEventListener('click', () => {
  sortField = 'marketcap'; sortDir = 'desc'; currentPage = 1;
  document.getElementById('sortMarketCap').classList.add('active');
  document.getElementById('sortVolume').classList.remove('active');
  renderTable();
});
document.getElementById('sortVolume').addEventListener('click', () => {
  sortField = 'volume'; sortDir = 'desc'; currentPage = 1;
  document.getElementById('sortVolume').classList.add('active');
  document.getElementById('sortMarketCap').classList.remove('active');
  renderTable();
});

// ─── CATEGORY TABS ───────────────────────────────────────────────────────────

document.getElementById('categoryTabs').addEventListener('click', e => {
  const btn = e.target.closest('[data-cat]');
  if (!btn) return;
  document.querySelectorAll('[data-cat]').forEach(b => b.classList.remove('active'));
  btn.classList.add('active');
  currentCat = btn.dataset.cat;
  currentPage = 1;
  renderTable();
});

// ─── NETWORK TABS ────────────────────────────────────────────────────────────

document.getElementById('networkTabs').addEventListener('click', e => {
  const btn = e.target.closest('[data-net]');
  if (!btn) return;
  document.querySelectorAll('[data-net]').forEach(b => b.classList.remove('active'));
  btn.classList.add('active');
  currentNet = btn.dataset.net;
  currentPage = 1;
