});

// ─── FILTER / COLUMNS PANELS ─────────────────────────────────────────────────

document.getElementById('toggleFiltersBtn').addEventListener('click', () => {
  const panel = document.getElementById('filterPanel');
  panel.classList.toggle('open');
  document.getElementById('columnsPanel').classList.remove('open');
});

document.getElementById('toggleColumnsBtn').addEventListener('click', () => {
  const panel = document.getElementById('columnsPanel');
  panel.classList.toggle('open');
  document.getElementById('filterPanel').classList.remove('open');
});

// Column visibility toggles
document.querySelectorAll('.col-toggle input').forEach(cb => {
  cb.addEventListener('change', () => {
    const col = cb.dataset.col;
    const show = cb.checked;
    document.querySelectorAll('.col-' + col).forEach(el => {
      el.style.display = show ? '' : 'none';
    });
  });
});

// ─── PROMO CAROUSEL ──────────────────────────────────────────────────────────

let promoIdx = 0;
const promoSlides = document.querySelectorAll('.promo-slide');
const promoDots = document.querySelectorAll('.promo-dot');

function showPromo(idx) {
  promoSlides.forEach((s, i) => s.classList.toggle('active', i === idx));
  promoDots.forEach((d, i) => d.classList.toggle('active', i === idx));
  promoIdx = idx;
}

setInterval(() => showPromo((promoIdx + 1) % promoSlides.length), 4000);

promoDots.forEach(dot => {
  dot.addEventListener('click', e => {
    e.stopPropagation();
    showPromo(parseInt(dot.dataset.idx, 10));
  });
});

// ─── READ MORE ───────────────────────────────────────────────────────────────

document.getElementById('readMoreBtn').addEventListener('click', () => {
  const extra = document.getElementById('msExtra');
  const btn = document.getElementById('readMoreBtn');
  if (extra.style.display === 'block') {
    extra.style.display = 'none';
    btn.textContent = 'Read More ▾';
  } else {
    extra.style.display = 'block';
    btn.textContent = 'Show Less ▴';
  }
});

// ─── STAR TOGGLE ─────────────────────────────────────────────────────────────

document.getElementById('tableBody').addEventListener('click', e => {
  const star = e.target.closest('.star-icon');
  if (!star) return;
  star.textContent = star.textContent === '☆' ? '★' : '☆';
  star.style.color = star.textContent === '★' ? '#f59e0b' : '';
});

// ─── INIT ─────────────────────────────────────────────────────────────────────

renderTable();
setupPagination();
</script>
